import { useEffect, useState } from 'react';
import axios from '../api/axios'; // Import axios instance to manage API requests

function Profile() {
  const [user, setUser] = useState(null);
  const [message, setMessage] = useState('');

  useEffect(() => {
    const fetchProfile = async () => {
      const token = localStorage.getItem('token'); // Get token from localStorage

      // Check if the token is available
      if (!token) {
        setMessage('You are not logged in.');
        return;
      }

      try {
        // Send GET request to fetch profile with Authorization token
        const res = await axios.get('/profile', {
          headers: {
            Authorization: `Bearer ${token}`,  // Send token in Authorization header
          },
        });
        
        // If request is successful, update user state with profile data
        setUser(res.data);  
      } catch (err) {
        console.error('Profile fetch error:', err);

        // If request fails, display message and optionally remove invalid token
        setMessage('Failed to fetch profile. Please log in again.');
        localStorage.removeItem('token');  // Optional: auto-logout if token is invalid
      }
    };

    // Call fetchProfile when component mounts
    fetchProfile();
  }, []);

  return (
    <div className="container mt-5">
      <h2>My P</h2>
      
      {/* Display any message related to login or error */}
      {message && <div className="alert alert-warning">{message}</div>}
      
      {/* If user data is available, display it */}
      {user ? (
        <div className="card p-3 mt-3 shadow">
          <p><strong>Name:</strong> {user.name}</p>
          <p><strong>Email:</strong> {user.email}</p>
          <p><strong>Role:</strong> {user.role}</p>
        </div>
      ) : (
        // If there's no user data yet and no message, show loading state
        !message && <p>Loading...</p>
      )}
    </div>
  );
}

export default Profile;
